nt relative to top-left of display\",\n                    \"default\": 0\n                  },\n                  \"y\": {\n                    \"type\": \"integer\",\n                    \"minimum\": -4096,\n                    \"maximum\": 4095,\n                    \"description\": \"Y coordinate of selected anchor point relative to top-left of display\",\n                    \"default\": 0\n                  },\n                  \"display\": {\n                    \"type\": \"string\",\n                    \"enum\": [\n                      \"front\",\n                      \"back\"\n                    ],\n                    \"description\": \"Which display to show the element on (for dual-display devices)\",\n                    \"default\": \"front\"\n                  },\n                  \"align\": {\n                    \"type\": \"string\",\n                    \"description\": \"Anchor point of element. Also use `x` and `y` to position element.\",\n                    \"enum\": [\n                      \"top_left\",\n                      \"top_mid\",\n                      \"top_right\",\n                      \"mid_left\",\n                      \"center\",\n                      \"mid_right\",\n                      \"bottom_left\",\n                      \"bottom_mid\",\n                      \"bottom_right\"\n                    ]\n                  },\n                  \"z_index\": {\n                    \"type\": \"integer\",\n                    \"minimum\": 0,\n                    \"maximum\": 2147483647,\n                    \"description\": \"Order of the element. Elements with higher Z-indexes are drawn on top of those with lower ones.\"\n                  }\n                },\n                \"discriminator\": {\n                  \"propertyName\": \"type\",\n                  \"mapping\": {\n                    \"text\": \"#/components/schemas/TextElement\",\n                    \"image\": \"#/components/schemas/ImageElement\",\n    