h","choices":[],"defaultValue":""},{"name":"new_path","location":"query","required":true,"detail":"New location path","choices":[],"defaultValue":""}],"contentType":"","bodyTemplate":"","bodySchema":""},{"id":"getStorageStatus","path":"/storage/status","method":"GET","title":"Show storage usage","detail":"Retrieves information about storage partition capacity, including total, used, and free space in bytes","group":"Storage","parameters":[],"contentType":"","bodyTemplate":"","bodySchema":""},{"id":"connectWebSocket","path":"/status/ws","method":"GET","title":"Device status streaming WebSocket endpoint","detail":"WebSocket connection for real-time device status and screen streaming.\nUpgrade from HTTP to WebSocket protocol is required.\nAfter connection, client must enable streaming by sending JSON: {\"enable\": true}\n","group":"Streaming","parameters":[],"contentType":"","bodyTemplate":"","bodySchema":""},{"id":"get_api_screen","path":"/screen","method":"GET","title":"Get single frame for requested screen","detail":"Captures and returns a single static image frame of the specified display (Front or Back)","group":"Streaming","parameters":[{"name":"display","location":"query","required":true,"detail":"Type of the display Front = 0, Back = 1","choices":[],"defaultValue":""}],"contentType":"","bodyTemplate":"","bodySchema":""},{"id":"getVersion","path":"/version","method":"GET","title":"Get API version information","detail":"Retrieves API version","group":"System","parameters":[],"contentType":"","bodyTemplate":"","bodySchema":""},{"id":"getTransport","path":"/transport","method":"GET","title":"Get device network connection info","detail":"Retrieves device transport type (usb/wifi)","group":"System","parameters":[],"contentType":"","bodyTemplate":"","bodySchema":""},{"id":"getStatus","path":"/status","method":"GET","title":"Get device status","detail":"Get device status","group":"System","parameters":[],"contentType":"","bodyTemplate":"","bodySchema":""},{"id":"getSta