atic\"\n          ]\n        },\n        \"address\": {\n          \"type\": \"string\",\n          \"example\": \"192.168.50.5\"\n        },\n        \"mask\": {\n          \"type\": \"string\",\n          \"example\": \"255.255.255.0\"\n        },\n        \"gateway\": {\n          \"type\": \"string\",\n          \"example\": \"192.168.50.1\"\n        }\n      }\n    }\n  }\n}"},{"id":"post_api_wifi_disconnect","path":"/wifi/disconnect","method":"POST","title":"post_api_wifi_disconnect","detail":"Disconnects from Wi-Fi","group":"Wi-Fi","parameters":[],"contentType":"","bodyTemplate":"","bodySchema":""},{"id":"getWifiNetworks","path":"/wifi/networks","method":"GET","title":"Scan for available Wi-Fi networks","detail":"Scans to discover nearby available Wi-Fi networks and returns their SSIDs, security styles, and signal strengths","group":"Wi-Fi","parameters":[],"contentType":"","bodyTemplate":"","bodySchema":""}]
